package Controllers; import Services.*; import Models.Order; import java.io.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/BuyProductsServlet") public class BuyProductsServlet extends HttpServlet{private final CartService c=new CartService();private final OrderService o=new OrderService();protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{Order order=o.checkout("Le The Vinh",c.cart(r.getSession()));p.sendRedirect("ViewOrderDetailsForCustomer?id="+order.getId());}}
